INSERT INTO `spell_ranks` (`first_spell_id`, `spell_id`, `rank`) VALUES (66216, 66216, 1), (66216, 66988, 2), (66216, 66989, 3), (66216, 66990, 4), (66216, 66991, 5), (66216, 66992, 6);
INSERT INTO `spell_ranks` (`first_spell_id`, `spell_id`, `rank`) SELECT `r`.`first_spell_id`, `m`.`new_id`, `r`.`rank` + `m`.`step` FROM `dc_tmp_rank_map` AS `m` JOIN `spell_ranks` AS `r` ON `r`.`spell_id` = `m`.`top_id`;
INSERT INTO `trainer_spell` (`TrainerId`, `SpellId`, `MoneyCost`, `ReqSkillLine`, `ReqSkillRank`, `ReqAbility1`, `ReqAbility2`, `ReqAbility3`, `ReqLevel`, `VerifiedBuild`) SELECT `t`.`TrainerId`, `m`.`new_id`, `t`.`MoneyCost`, `t`.`ReqSkillLine`, `t`.`ReqSkillRank`, `m`.`prev_id`, `t`.`ReqAbility2`, `t`.`ReqAbility3`, `m`.`band`, 0 FROM `dc_tmp_rank_map` AS `m` JOIN `trainer_spell` AS `t` ON `t`.`SpellId` = `m`.`top_id` WHERE `m`.`is_parent` = 1;
INSERT INTO `spell_bonus_data` (`entry`, `direct_bonus`, `dot_bonus`, `ap_bonus`, `ap_dot_bonus`, `comments`) SELECT `m`.`new_id`, `b`.`direct_bonus`, `b`.`dot_bonus`, `b`.`ap_bonus`, `b`.`ap_dot_bonus`, `b`.`comments` FROM `dc_tmp_rank_map` AS `m` JOIN `spell_bonus_data` AS `b` ON `b`.`entry` = `m`.`bonus_src`;
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) SELECT `m`.`new_id`, `s`.`ScriptName` FROM `dc_tmp_rank_map` AS `m` JOIN `spell_script_names` AS `s` ON `s`.`spell_id` = `m`.`top_id`;
INSERT INTO `spell_custom_attr` (`spell_id`, `attributes`) SELECT `m`.`new_id`, `a`.`attributes` FROM `dc_tmp_rank_map` AS `m` JOIN `spell_custom_attr` AS `a` ON `a`.`spell_id` = `m`.`top_id`;
INSERT INTO `spell_threat` (`entry`, `flatMod`, `pctMod`, `apPctMod`) SELECT `m`.`new_id`, `t`.`flatMod` * `m`.`growth`, `t`.`pctMod`, `t`.`apPctMod` FROM `dc_tmp_rank_map` AS `m` JOIN `spell_threat` AS `t` ON `t`.`entry` = `m`.`top_id`;
INSERT INTO `spell_linked_spell` (`spell_trigger`, `spell_effect`, `type`, `comment`) SELECT CASE WHEN `l`.`spell_trigger` < 0 THEN -`m`.`new_id` ELSE `m`.`new_id` END, CASE WHEN `c`.`new_id` IS NULL THEN `l`.`spell_effect` ELSE `c`.`new_id` END, `l`.`type`, `l`.`comment` FROM `dc_tmp_rank_map` AS `m` JOIN `spell_linked_spell` AS `l` ON `l`.`spell_trigger` IN (`m`.`top_id`, -`m`.`top_id`) LEFT JOIN `dc_tmp_rank_map2` AS `c` ON `c`.`top_id` = `l`.`spell_effect` AND `c`.`step` = `m`.`step`;
